<script setup lang="ts">
import { copyText } from '../clipboard'
import { computed,onUnmounted,reactive,ref,watch } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import PageShell from '../PageShell.vue'
import {usePage} from '../page'
import {api} from '../api'
import {loadSite} from '../site'
type SMTP={host:string;port:number;security:string;username:string;password:string;from:string;from_name:string}
type Settings={registration_email_verification:boolean;force_invite:boolean;terms_url:string;privacy_url:string;registration_enabled:boolean;captcha_mode:string;smtp:SMTP;referral_enabled:boolean;referral_mode:string;referral_rate:string;site_name:string;panel_url:string;agent_host:string;agent_port:number;agent_transport:string;installer_url:string;release_base_url:string;agent_version:string;install_token_minutes:number;proxy_trusted_cidrs:string[];target_deny_cidrs:string[]}
const form=reactive<Settings>({registration_email_verification:true,force_invite:false,terms_url:'',privacy_url:'',registration_enabled:false,captcha_mode:'image',smtp:{host:'',port:587,security:'starttls',username:'',password:'',from:'',from_name:''},referral_enabled:false,referral_mode:'first',referral_rate:'15',site_name:'Nekopass',panel_url:'',agent_host:'',agent_port:9443,agent_transport:'tls',installer_url:'https://github.com/hajidishu/nekopass/releases/latest/download/install-agent.sh',release_base_url:'https://github.com/hajidishu/nekopass/releases/download',agent_version:'latest',install_token_minutes:30,proxy_trusted_cidrs:[],target_deny_cidrs:[]})
watch(()=>form.referral_enabled,value=>{if(!value)form.force_invite=false})
const proxyTrustText=ref(''),targetDenyText=ref('')
const cidrs=(text:string)=>text.split(/[,\s]+/).filter(Boolean)
const updateInfo=ref<{current_version:string;latest:{version:string;url:string};update_available:boolean}|null>(null),checkingUpdate=ref(false)
async function checkUpdate(){checkingUpdate.value=true;try{updateInfo.value=await api('admin/updates')}catch(e){ElMessage.error((e as Error).message)}finally{checkingUpdate.value=false}}
type PanelUpdateStatus={supported:boolean;current_version:string;task:{version:string;state:string;error?:string}|null}
const panelStatus=ref<PanelUpdateStatus|null>(null),submittingUpdate=ref(false)
const updating=computed(()=>panelStatus.value?.task?.state==='queued'||panelStatus.value?.task?.state==='running')
const updateText:Record<string,string>={queued:'等待更新',running:'正在更新，面板可能短暂重启',completed:'更新完成',failed:'更新失败'}
let updateTimer:ReturnType<typeof setTimeout>|undefined,stopped=false
onUnmounted(()=>{stopped=true;if(updateTimer)clearTimeout(updateTimer)})
async function pollPanelUpdate(){
 if(stopped)return
 try{
  panelStatus.value=await api<PanelUpdateStatus>('admin/updates/panel')
  if(panelStatus.value.task?.state==='completed'&&updatingBeforePoll){ElMessage.success('面板更新完成');updateTimer=setTimeout(()=>{if(!stopped)location.reload()},1200);return}
 }catch{/* Retry while the service restarts. */}
 if(!stopped&&updating.value)updateTimer=setTimeout(()=>{updatingBeforePoll=true;void pollPanelUpdate()},2000)
}
let updatingBeforePoll=false
async function updatePanel(){
 submittingUpdate.value=true
 try{
  const info=await api<NonNullable<typeof updateInfo.value>>('admin/updates');updateInfo.value=info
  if(!info.update_available){ElMessage.info('已是最新版本');return}
  const task=await api<NonNullable<PanelUpdateStatus['task']>>('admin/updates/panel','POST',{version:info.latest.version})
  panelStatus.value={supported:true,current_version:info.current_version,task};updatingBeforePoll=true
  ElMessage.success('更新任务已提交');void pollPanelUpdate()
 }catch(e){ElMessage.error((e as Error).message)}finally{submittingUpdate.value=false}
}
const listener=ref<{address:string;mode:string}|null>(null)
const hasKey=ref(false),customKey=ref(''),shownKey=ref(''),keyDialog=ref(false)
async function loadSettings(){const data=await api<{settings:Settings;api_key_configured:boolean;agent_listener:{address:string;mode:string}|null}>('admin/settings');Object.assign(form,data.settings);proxyTrustText.value=(form.proxy_trusted_cidrs||[]).join('\n');targetDenyText.value=(form.target_deny_cidrs||[]).join('\n');hasKey.value=data.api_key_configured;listener.value=data.agent_listener}
const {me,loading,error,busy,run}=usePage(async()=>{await loadSettings();await pollPanelUpdate()},{admin:true})
function currentAddress(){form.panel_url=location.origin;form.agent_host=location.hostname.replace(/^\[|\]$/g,'')}
async function save(){await run(async()=>{await api('admin/settings','PUT',{...form,proxy_trusted_cidrs:cidrs(proxyTrustText.value),target_deny_cidrs:cidrs(targetDenyText.value)});await loadSettings();await loadSite();ElMessage.success('系统设置已保存')})}
async function key(){try{if(hasKey.value)await ElMessageBox.confirm('生成或设置新密钥会使旧管理 API 密钥失效。','更新管理密钥',{confirmButtonText:'更新',cancelButtonText:'取消'});await run(async()=>{const data=await api<{key:string}>('admin/settings/api-key','POST',{key:customKey.value});shownKey.value=data.key;customKey.value='';hasKey.value=true;keyDialog.value=true})}catch{/* cancelled */}}
async function revoke(){try{await ElMessageBox.confirm('撤销后，现有管理 API 密钥将不能调用后台接口。','撤销管理密钥',{confirmButtonText:'撤销',cancelButtonText:'取消'});await run(async()=>{await api('admin/settings/api-key','DELETE',{});hasKey.value=false;ElMessage.success('管理 API 密钥已撤销')})}catch{/* cancelled */}}
async function copyKey(){try{await copyText(shownKey.value);ElMessage.success('密钥已复制')}catch{ElMessage.warning('复制失败，请手动选择复制')}}
</script>
<template><PageShell :me="me" :loading="loading" :error="error" active="settings" admin><section class="surface"><div class="section-header"><strong>系统设置</strong><el-button type="primary" :loading="busy" @click="save">保存设置</el-button></div><div class="section-body settings-form"><el-form label-position="top" @submit.prevent="save"><div class="form-section-title">软件更新</div><el-button :loading="checkingUpdate" @click="checkUpdate">检查更新</el-button><el-button type="primary" :loading="submittingUpdate||updating" :disabled="!panelStatus?.supported||updating" @click="updatePanel">立即更新</el-button><p v-if="panelStatus?.task" class="field-tip">{{updateText[panelStatus.task.state]||panelStatus.task.state}} · {{panelStatus.task.version}} {{panelStatus.task.error||''}}</p><p v-if="panelStatus&&!panelStatus.supported" class="field-tip">更新暂不可用，请检查服务状态。更新组件随软件安装和升级自动部署。</p><p v-if="updateInfo" class="field-tip">当前主控 {{updateInfo.current_version}} · 最新版本 <a :href="updateInfo.latest.url" target="_blank" rel="noopener">{{updateInfo.latest.version}}</a> · {{updateInfo.update_available?'有可用更新':'已是最新版本'}}。点击「立即更新」升级面板，更新时会短暂重启；节点更新在节点管理操作。</p><div class="form-section-title">站点与连接地址</div><el-form-item label="站点名称"><el-input v-model="form.site_name" maxlength="64" /></el-form-item><el-form-item label="面板对外地址"><el-input v-model="form.panel_url" placeholder="https://panel.example.com" /><el-button class="settings-inline-action" @click="currentAddress">填入当前面板地址</el-button></el-form-item><div class="form-grid"><el-form-item label="Agent 主控域名 / IP"><el-input v-model="form.agent_host" placeholder="panel.example.com" /></el-form-item><el-form-item label="Agent 控制端口"><el-input-number v-model="form.agent_port" :min="1" :max="65535" /></el-form-item></div><el-form-item label="节点连接方式"><el-select v-model="form.agent_transport"><el-option label="HTTPS（公共证书 / Nginx 代理）" value="tls"/><el-option label="HTTP（明文 HTTP/2）" value="plain"/></el-select><span class="field-tip">保存后立即切换主控连接方式，无需重启。HTTP 会关闭控制端口 TLS；HTTPS 使用已配置的证书，或已有 Nginx TLS 代理。</span></el-form-item><p class="field-tip">填写节点能访问的外部地址和端口。在线的 v0.14.1 及以上节点会自动接收新地址；离线或旧版本节点需重新执行安装命令。HTTP 直连需放行主控控制端口。</p><p v-if="listener" class="field-tip">当前控制监听：{{listener.address}} · {{listener.mode==='tls'?'TLS':listener.mode==='proxy'?'Nginx TLS 代理后端':'HTTP'}}</p><div class="form-section-title">用户注册</div><el-form-item label="开放注册"><el-switch v-model="form.registration_enabled"/><span class="field-tip">关闭后仅管理员可以创建用户。</span></el-form-item><el-form-item label="注册邮件验证"><el-switch v-model="form.registration_email_verification"/><span class="field-tip">开启时须配置 SMTP 并验证邮箱；关闭后注册无需邮件验证码，人机验证仍按下方设置执行。</span></el-form-item><el-form-item label="强制邀请注册"><el-switch v-model="form.force_invite" :disabled="!form.referral_enabled"/><span class="field-tip">须先开启邀请返利。开启后必须填写有效的老用户邀请码。</span></el-form-item><el-form-item label="用户条款 URL"><el-input v-model="form.terms_url" placeholder="https://example.com/terms"/></el-form-item><el-form-item label="隐私条款 URL"><el-input v-model="form.privacy_url" placeholder="https://example.com/privacy"/></el-form-item><el-form-item label="人机验证方式"><el-select v-model="form.captcha_mode"><el-option label="关闭" value="off"/><el-option label="图形验证码" value="image"/></el-select><span class="field-tip">注册与创建工单共用此设置。</span></el-form-item><div class="form-section-title">SMTP 邮件服务</div><div class="form-grid"><el-form-item label="SMTP 主机"><el-input v-model="form.smtp.host" placeholder="smtp.example.com"/></el-form-item><el-form-item label="SMTP 端口"><el-input-number v-model="form.smtp.port" :min="1" :max="65535"/></el-form-item><el-form-item label="SMTP 连接方式"><el-select v-model="form.smtp.security"><el-option label="STARTTLS（通常 587）" value="starttls"/><el-option label="TLS（通常 465）" value="tls"/><el-option label="明文（本机 / 无认证中继）" value="plain"/></el-select></el-form-item><el-form-item label="SMTP 用户名"><el-input v-model="form.smtp.username" autocomplete="off"/></el-form-item><el-form-item label="SMTP 密码 / 授权码"><el-input v-model="form.smtp.password" type="password" show-password autocomplete="new-password"/></el-form-item><el-form-item label="发件邮箱"><el-input v-model="form.smtp.from" type="email"/></el-form-item><el-form-item label="发件名称"><el-input v-model="form.smtp.from_name"/></el-form-item></div><div class="form-section-title">邀请返利</div><el-form-item label="启用邀请返利"><el-switch v-model="form.referral_enabled"/></el-form-item><div class="form-grid"><el-form-item label="默认返利类型"><el-select v-model="form.referral_mode"><el-option label="首次返利" value="first"/><el-option label="循环返利" value="recurring"/></el-select></el-form-item><el-form-item label="默认返利比例"><el-input v-model="form.referral_rate" inputmode="decimal"><template #append>%</template></el-input></el-form-item></div><p class="field-tip">仅大于 0 元的套餐购买和续费参与返利，充值及免费套餐不计算。个人设置在用户管理中调整。</p><div class="form-section-title">转发安全</div><el-form-item label="PROXY Protocol 信任来源"><el-input v-model="proxyTrustText" type="textarea" :rows="4" placeholder="每行一个 CIDR，例如 192.0.2.10/32" /><span class="field-tip">只信任这些来源提供的客户端 IP；留空禁止规则接收 PROXY Protocol。仅管理员可以修改。</span></el-form-item><el-form-item label="禁止转发的目标 IP 网段"><el-input v-model="targetDenyText" type="textarea" :rows="10" placeholder="每行一个 IPv4 / IPv6 CIDR" /><span class="field-tip">直转和隧道出口均检查实际解析后的 IP。默认禁止本机、内网、链路本地、组播、云 metadata 等特殊地址；需要内网转发时移除对应网段，留空允许全部目标。旧节点须升级后才能执行这些限制。</span></el-form-item><div class="form-section-title">节点一键安装</div><p class="field-tip">一键安装始终可用。默认从 GitHub Releases 下载，也可修改为自己的 HTTPS 下载源。</p><el-form-item label="安装脚本地址"><el-input v-model="form.installer_url" placeholder="https://github.com/hajidishu/nekopass/releases/latest/download/install-agent.sh" /></el-form-item><el-form-item label="Agent 版本下载根地址"><el-input v-model="form.release_base_url" placeholder="https://github.com/hajidishu/nekopass/releases/download" /></el-form-item><div class="form-grid"><el-form-item label="Agent 版本"><el-input v-model="form.agent_version" placeholder="latest" /></el-form-item></div><el-button type="primary" :loading="busy" native-type="submit">保存设置</el-button></el-form><div class="form-section-title api-key-section">管理 API 密钥</div><p class="subtle">{{hasKey?'已配置管理 API 密钥。原值不会再次显示。':'尚未配置管理 API 密钥。'}}此密钥用于自动化管理接口，不是节点密钥，也不会包含在节点安装命令中。</p><el-input v-model="customKey" type="password" show-password autocomplete="new-password" placeholder="可填写 32–256 字符自定义密钥，留空自动生成" /><div class="admin-actions settings-key-actions"><el-button :loading="busy" @click="key">{{hasKey?'更新管理 API 密钥':'生成管理 API 密钥'}}</el-button><el-button v-if="hasKey" type="danger" plain :loading="busy" @click="revoke">撤销密钥</el-button></div></div></section><el-dialog v-model="keyDialog" title="保存管理 API 密钥" width="600px" @closed="shownKey=''" ><p>只显示这一次，请保存到自己的密钥管理工具中。</p><el-input :model-value="shownKey" type="textarea" :rows="3" readonly /><template #footer><el-button type="primary" @click="copyKey">复制密钥</el-button></template></el-dialog></PageShell></template>
